import { expertDashboard } from './dashboard.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const input=(key,label,p,required=false)=>`<label class="field"><span>${label}</span><input name="${key}" value="${esc(p[key]||'')}" maxlength="${key==='organization'?250:200}" ${required?'required':''}></label>`;
const select=(key,label,p,options)=>`<label class="field"><span>${label}</span><select name="${key}"><option value="">Не указывать</option>${options.map(v=>`<option ${p[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
export function profilePage(profile,account,error=''){
 const p=profile||{},expert=account.role==='expert';return `<div class="stack"><div class="page-head"><p class="eyebrow">${p.fullName?'МОЙ ПРОФИЛЬ':'ПЕРВЫЙ ВХОД'}</p><h1>${p.fullName?'Личные данные':'Давайте познакомимся'}</h1><p>Заполните рабочие данные для кабинета ${expert?'эксперта':'госслужащего'}. Фото и дополнительные вопросы необязательны.</p></div>${error?`<p class="error-message" role="alert">${esc(error)}</p>`:''}<form id="profile-form" class="stack" data-revision="${p.revision||0}"><section class="card stack"><h2>Основные данные</h2><div class="profile-photo"><img id="avatar-preview" class="avatar" alt="Фото профиля" ${p.avatar?`src="${esc(p.avatar)}"`:'hidden'}><label class="field"><span>Фото профиля — JPEG, PNG или WebP, до 5 МБ</span><input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp"></label></div>${p.avatar?'<label class="radio"><input name="removeAvatar" type="checkbox">Удалить фото</label>':''}<div class="profile-grid">${input('fullName','ФИО',{...p,fullName:p.fullName||account.displayName},true)}${input('organization',expert?'Организация / независимая практика':'Государственный орган / учреждение',p,true)}${input('department','Подразделение (или «не применимо»)',p,true)}${input('position','Должность',p,true)}</div>${expert?input('registryNumber','Реквизиты аккредитации — при наличии',p)+'<p class="muted">Сведения указываете вы. Аккредитация не проверяется автоматически.</p>':''}</section><section class="card stack"><h2>Дополнительно — по желанию</h2><p class="muted">Для понимания потребностей пользователей. Можно оставить все поля пустыми. Данные сохраняются в вашем профиле; публичная статистика по ним пока не формируется.</p><div class="profile-grid">${select('experience','Опыт работы',p,['Менее года','1–3 года','4–10 лет','Более 10 лет'])}${input('field','Сфера работы',p)}</div><label class="field"><span>Какие задачи вы хотите решить с помощью системы?</span><textarea name="goals" maxlength="1500" rows="3">${esc(p.goals||'')}</textarea></label></section><button class="btn primary" type="submit">Сохранить и открыть кабинет</button></form></div>`;
}
export function profileSummary(p){if(!p)return '';return `<section class="card profile-summary">${p.avatar?`<img class="avatar" alt="Фото ${esc(p.fullName)}" src="${esc(p.avatar)}">`:`<span class="avatar avatar-placeholder" aria-hidden="true">${esc(p.fullName?.slice(0,1))}</span>`}<div><h2>${esc(p.fullName)}</h2><p>${esc(p.position)} · ${esc(p.department)}</p><p class="muted">${esc(p.organization)}</p></div><a class="btn" href="#profile">Изменить профиль</a></section>`;}
export function expertOverview(cases,options={}){return expertDashboard(cases,options);}
